// Monta o e-mail do evento (seção 4.3 da especificação). Sem responsável, o aviso vai para o e-mail de admin.
const evento = $json.body || {};
const lead = evento.lead || {};
const responsavel = evento.responsavel || null;
const dados = evento.dados || {};
const emailAdmin = $json.emailAdmin;

const origens = { meta_lead_ads: 'Meta', google_ads: 'Google Ads', site: 'Site', whatsapp: 'WhatsApp', telefone: 'Telefone', indicacao: 'Indicação', planilha: 'Planilha', manual: 'Cadastro manual' };
const plataformas = { facebook: 'Facebook', instagram: 'Instagram', google: 'Google' };
function nomeDaOrigem(origem, plataforma) {
  const nome = origens[origem] || origem || 'não informada';
  const onde = plataformas[plataforma];
  return onde ? nome + ' (' + onde + ')' : nome;
}

const nome = lead.nome || 'Lead sem nome';
const ficha = [
  ['Nome', lead.nome],
  ['Empresa', lead.empresa],
  ['UF', lead.uf],
  ['Origem', nomeDaOrigem(lead.origem, lead.plataforma)],
  ['Campanha', lead.campanha],
  ['Etapa', lead.etapa && lead.etapa.nome],
].filter(function (par) { return par[1]; }).map(function (par) { return par[0] + ': ' + par[1]; }).join('\n');

let assunto;
let abertura;
if (evento.tipo === 'lead.criado') {
  assunto = responsavel ? 'Novo lead para você: ' + nome : 'Lead novo sem responsável: ' + nome;
  abertura = responsavel
    ? 'Você recebeu um lead novo no CRM.'
    : 'Chegou um lead novo e ele ficou sem responsável. Escolha quem vai atendê-lo na ficha.';
} else if (evento.tipo === 'lead.entrada_repetida') {
  assunto = responsavel ? 'Nova entrada de um lead seu: ' + nome : 'Nova entrada de um lead sem responsável: ' + nome;
  abertura = 'Este lead entrou em contato de novo, pela origem ' + nomeDaOrigem(dados.origem) + (dados.campanha ? ', na campanha ' + dados.campanha : '') + '.';
} else if (evento.tipo === 'lead.reatribuido') {
  assunto = responsavel ? 'Lead passado para você: ' + nome : 'Lead sem responsável ativo: ' + nome;
  abertura = dados.responsavelAnterior
    ? 'Este lead estava com ' + dados.responsavelAnterior.nome + ' e foi passado para ' + (responsavel ? 'você' : 'um usuário desativado') + '.'
    : 'Este lead estava sem responsável e foi passado para ' + (responsavel ? 'você' : 'um usuário desativado') + '.';
} else {
  // Os outros tipos (como lead.etapa_alterada) não geram e-mail.
  return { json: { enviar: false, tipo: evento.tipo || null } };
}

const saudacao = responsavel ? 'Olá, ' + responsavel.nome + '.' : 'Olá.';
return {
  json: {
    enviar: true,
    tipo: evento.tipo,
    destinatario: (responsavel && responsavel.email) || emailAdmin,
    assunto: assunto,
    mensagem: saudacao + '\n\n' + abertura + '\n\n' + ficha + '\n\nAbrir a ficha: ' + lead.url + '\n',
  },
};
